/**
 * VIGILANT demo recorder — Phase 4
 *
 * Records each scene of the demo video as a separate MP4 clip into demo/clips/.
 * Scenes 1 and 8 (title cards) are generated by build.sh; this script covers
 * scenes 2–7 (live browser footage).
 *
 * Prerequisites:
 *   npm install -D playwright @playwright/test
 *   npx playwright install chromium
 *
 * Usage:
 *   # Start frontend + backend first:
 *   #   cd frontend && npm run dev          (port 3000)
 *   #   DATABASE_URL=sqlite:///./demo.db RING_INTEGRATION_MODE=simulator \
 *   #     RING_HMAC_SIGNING_KEY=<your-demo-hmac-key> \
 *   #     HOME_TIMEZONE=Asia/Kolkata uvicorn api.index:app --port 8001
 *   #   (run scripts/demo_scenario.py --reset first)
 *   #
 *   npx ts-node demo/record.ts
 *   # or: npx tsx demo/record.ts
 */

import { chromium, Browser, BrowserContext, Page } from "playwright";
import * as path from "path";
import * as fs from "fs";

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

const FRONTEND     = "http://localhost:3000";
const ARCH_PNG     = path.resolve(__dirname, "../docs/architecture.png");
const CLIPS_DIR    = path.resolve(__dirname, "clips");
const VIDEO_SIZE   = { width: 1920, height: 1080 };

// Pattern types to click in the demo (matched by data-pattern-type attribute
// or innerText of the type label — whichever the component renders)
const RAPID_RETURN_TYPE    = "rapid_return";
const LATE_FIRST_TYPE      = "late_first_activity";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const sleep = (ms: number) => new Promise<void>(r => setTimeout(r, ms));

async function smoothMove(page: Page, x: number, y: number, steps = 40) {
  await page.mouse.move(x, y, { steps });
}

async function smoothScroll(page: Page, deltaY: number, steps = 8) {
  const step = deltaY / steps;
  for (let i = 0; i < steps; i++) {
    await page.mouse.wheel(0, step);
    await sleep(40);
  }
}

/** Open a new browser context with video recording into CLIPS_DIR/<name>.webm */
async function openScene(
  browser: Browser,
  name: string,
): Promise<{ ctx: BrowserContext; page: Page }> {
  const ctx = await browser.newContext({
    viewport: VIDEO_SIZE,
    recordVideo: { dir: CLIPS_DIR, size: VIDEO_SIZE },
  });
  const page = await ctx.newPage();
  // Tag so we can rename after close
  (page as any).__sceneName = name;
  return { ctx, page };
}

/** Close context and rename the recorded webm to <name>.webm */
async function closeScene(ctx: BrowserContext, name: string): Promise<string> {
  const pages = ctx.pages();
  const videoPath = await pages[0]?.video()?.path();
  await ctx.close();
  if (videoPath) {
    const dest = path.join(CLIPS_DIR, `${name}.webm`);
    fs.renameSync(videoPath, dest);
    console.log(`  saved → ${dest}`);
    return dest;
  }
  return "";
}

// ---------------------------------------------------------------------------
// Scene recorders
// ---------------------------------------------------------------------------

/**
 * Scene 2 — Dashboard Overview (0:15–0:40, 25 s)
 * Shows: banner stats, 7-day chart, pattern cards scrolling by.
 */
async function recordScene2(browser: Browser) {
  console.log("\n[Scene 2] Dashboard overview…");
  const { ctx, page } = await openScene(browser, "scene2_dashboard");

  await page.goto(FRONTEND, { waitUntil: "load" });
  await sleep(2500);  // let React render + API calls settle

  // Park cursor away from interactive elements
  await smoothMove(page, 960, 200);
  await sleep(800);

  // Slowly scan the banner (left → right)
  await smoothMove(page, 200, 140, 60);
  await sleep(600);
  await smoothMove(page, 1700, 140, 80);
  await sleep(800);

  // Drift cursor down to chart area
  await smoothMove(page, 960, 380, 60);
  await sleep(1000);

  // Gentle scroll to show pattern cards
  await smoothScroll(page, 320, 10);
  await sleep(1200);

  // Drift over first few cards
  await smoothMove(page, 400, 600, 40);
  await sleep(600);
  await smoothMove(page, 800, 640, 40);
  await sleep(500);
  await smoothMove(page, 1200, 600, 40);
  await sleep(800);

  // Scroll back up to banner
  await smoothScroll(page, -320, 10);
  await sleep(1000);

  return closeScene(ctx, "scene2_dashboard");
}

/**
 * Scene 3 — Rapid Return detail (0:40–1:15, 35 s)
 * Shows: click the rapid_return card → PatternDetail → MOTIF score breakdown.
 */
async function recordScene3(browser: Browser) {
  console.log("\n[Scene 3] Rapid return detail…");
  const { ctx, page } = await openScene(browser, "scene3_rapid_return");

  await page.goto(FRONTEND, { waitUntil: "load" });
  await sleep(2500);

  // Scroll down until a rapid_return card is visible
  let card = page.locator(`[data-pattern-type="${RAPID_RETURN_TYPE}"]`).first();
  // Fallback: find by text content if no data attribute
  if (!await card.isVisible().catch(() => false)) {
    card = page.locator("text=rapid_return").first();
  }

  await card.scrollIntoViewIfNeeded();
  await sleep(800);

  const box = await card.boundingBox();
  if (box) {
    await smoothMove(page, box.x + box.width * 0.5, box.y + box.height * 0.5, 50);
    await sleep(600);
    await card.click();
  }

  // Wait for PatternDetail to mount
  await page.waitForSelector("text=MOTIF Score", { timeout: 5000 }).catch(() => {});
  await sleep(1000);

  // Read the salience score area
  await smoothMove(page, 700, 400, 40);
  await sleep(800);

  // Drift down to show the event list
  await smoothScroll(page, 200, 8);
  await sleep(800);
  await smoothMove(page, 700, 600, 40);
  await sleep(1000);

  // Scroll back up to score breakdown
  await smoothScroll(page, -200, 8);
  await sleep(1000);

  return closeScene(ctx, "scene3_rapid_return");
}

/**
 * Scene 4 — Architecture diagram (1:15–1:35, 20 s)
 * Opens the architecture PNG directly in the browser (full-screen, centred on
 * a white background).  No browser chrome visible.
 */
async function recordScene4(browser: Browser) {
  console.log("\n[Scene 4] Architecture diagram…");
  const { ctx, page } = await openScene(browser, "scene4_architecture");

  // Render PNG full-screen via a minimal data page
  const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{background:#fff;display:flex;align-items:center;justify-content:center;
       width:1920px;height:1080px;overflow:hidden}
  img{max-width:1800px;max-height:1040px;object-fit:contain}
</style>
</head>
<body><img src="file://${ARCH_PNG}" /></body>
</html>`;

  await page.setContent(html, { waitUntil: "load" });
  await sleep(500);

  // Wait for image to render
  await page.waitForSelector("img", { state: "visible" });
  await sleep(18000); // hold for full 18 s scene

  return closeScene(ctx, "scene4_architecture");
}

/**
 * Scene 5 — Learning / Feedback (1:35–1:55, 20 s)
 * Shows: PatternDetail for rapid_return → click "This was normal" → salience updates.
 */
async function recordScene5(browser: Browser) {
  console.log("\n[Scene 5] Feedback / learning…");
  const { ctx, page } = await openScene(browser, "scene5_feedback");

  await page.goto(FRONTEND, { waitUntil: "load" });
  await sleep(1200);

  // Navigate to rapid_return card
  let card = page.locator(`[data-pattern-type="${RAPID_RETURN_TYPE}"]`).first();
  if (!await card.isVisible().catch(() => false)) {
    card = page.locator("text=rapid_return").first();
  }
  await card.scrollIntoViewIfNeeded();
  await sleep(600);
  await card.click();

  await page.waitForSelector("text=MOTIF Score", { timeout: 5000 }).catch(() => {});
  await sleep(1200);

  // Find and click "This was normal" feedback button
  const normalBtn = page.locator("text=This was normal").first();
  const normalBtnAlt = page.locator("button:has-text('normal')").first();

  const feedbackBtn = await normalBtn.isVisible().catch(() => false) ? normalBtn : normalBtnAlt;

  const btnBox = await feedbackBtn.boundingBox().catch(() => null);
  if (btnBox) {
    await smoothMove(page, btnBox.x + btnBox.width * 0.5, btnBox.y + btnBox.height * 0.5, 50);
    await sleep(800);
    await feedbackBtn.click();
  }

  // Wait for score to update on screen
  await sleep(2000);
  await smoothMove(page, 700, 400, 30);
  await sleep(1500);

  return closeScene(ctx, "scene5_feedback");
}

/**
 * Scene 6 — Caretaking / Late First Activity (1:55–2:15, 20 s)
 * Shows: scroll to late_first_activity card → click → PatternDetail.
 */
async function recordScene6(browser: Browser) {
  console.log("\n[Scene 6] Late first activity / caretaking…");
  const { ctx, page } = await openScene(browser, "scene6_caretaking");

  await page.goto(FRONTEND, { waitUntil: "load" });
  await sleep(1200);

  let card = page.locator(`[data-pattern-type="${LATE_FIRST_TYPE}"]`).first();
  if (!await card.isVisible().catch(() => false)) {
    card = page.locator("text=late_first_activity").first();
  }

  await card.scrollIntoViewIfNeeded();
  await sleep(800);

  const box = await card.boundingBox();
  if (box) {
    await smoothMove(page, box.x + box.width * 0.5, box.y + box.height * 0.5, 50);
    await sleep(700);
    await card.click();
  }

  await page.waitForSelector("text=MOTIF Score", { timeout: 5000 }).catch(() => {});
  await sleep(1000);

  // Drift over the pattern explanation / type label
  await smoothMove(page, 700, 350, 40);
  await sleep(800);
  await smoothMove(page, 700, 500, 40);
  await sleep(1200);

  return closeScene(ctx, "scene6_caretaking");
}

/**
 * Scene 7 — Analytics close (2:15–2:30, 15 s)
 * Shows: back on dashboard, banner stats, 7-day chart.
 */
async function recordScene7(browser: Browser) {
  console.log("\n[Scene 7] Analytics close…");
  const { ctx, page } = await openScene(browser, "scene7_analytics");

  await page.goto(FRONTEND, { waitUntil: "load" });
  await sleep(1500);

  // Scan banner slowly
  await smoothMove(page, 200, 140, 60);
  await sleep(500);
  await smoothMove(page, 960, 140, 60);
  await sleep(500);
  await smoothMove(page, 1700, 140, 60);
  await sleep(600);

  // Drift down to chart
  await smoothMove(page, 960, 400, 50);
  await sleep(1200);

  // Click the "analytics" tab if it exists
  const analyticsTab = page.locator("text=analytics").first();
  if (await analyticsTab.isVisible().catch(() => false)) {
    const tabBox = await analyticsTab.boundingBox();
    if (tabBox) {
      await smoothMove(page, tabBox.x + tabBox.width * 0.5, tabBox.y + tabBox.height * 0.5, 40);
      await sleep(500);
      await analyticsTab.click();
      await sleep(2000);
    }
  }

  await smoothMove(page, 960, 500, 40);
  await sleep(1500);

  return closeScene(ctx, "scene7_analytics");
}

